import { describe, it, expect, jest } from '@jest/globals';
import { prisma } from '@teaching-engine/database';

describe('Debug Mock', () => {
  it('should check what prisma is', () => {
    expect(prisma).toBeDefined();
    expect(prisma.curriculumExpectation).toBeDefined();
    expect(prisma.curriculumExpectation.create).toBeDefined();
  });
  
  it('should check mock function', () => {
    const isMock = jest.isMockFunction(prisma.curriculumExpectation.create);
    expect(isMock).toBe(true);
  });
  
  it('should actually create data', async () => {
    const testData = {
      id: 'test-id',
      description: 'Test curriculum expectation',
      code: 'TEST-001',
      subject: 'Mathematics',
      grade: 1,
    };
    
    const created = await prisma.curriculumExpectation.create({
      data: testData,
    });
    
    // This is where we'll see what's actually returned
    expect(created).toBeDefined();
    expect(created).toMatchObject(testData);
  });
});